import{_ as a,C as e,c as o,o as t,j as i,G as s,b as n,a0 as r,a as l,w as d,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Toma de decisiones basada en la probabilidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/education/tactics/probability.md","filePath":"es/education/tactics/probability.md"}');const p=a({name:"es/education/tactics/probability.md"},[["render",function(a,u,p,m,b,h){const g=e("AdBanner"),f=e("Mermaid"),q=e("AdInArticle");return t(),o("div",null,[u[1]||(u[1]=i("h1",{id:"toma-de-decisiones-basada-en-la-probabilidad",tabindex:"-1"},[l("Toma de decisiones basada en la probabilidad "),i("a",{class:"header-anchor",href:"#toma-de-decisiones-basada-en-la-probabilidad","aria-label":'Permalink to "Toma de decisiones basada en la probabilidad"'},"​")],-1)),s(g),u[2]||(u[2]=i("p",null,"El pensamiento táctico de élite utiliza la probabilidad para tomar mejores decisiones. En lugar de adivinar o dejarse llevar por la intuición, se piensa sistemáticamente en las opciones.",-1)),u[3]||(u[3]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"La gran idea"),i("p",null,[i("strong",null,"Piense en probabilidades, no en certezas."),l(" La mejor decisión no siempre es la más agresiva ni la más segura: es la que le ofrece el mejor valor esperado en muchas situaciones similares.")])],-1)),(t(),n(c,null,{default:d(()=>[s(f,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BPunto%20de%20decisi%C3%B3n%5D%20--%3E%20B%5BOpci%C3%B3n%201%5D%0A%20%20%20%20A%20--%3E%20C%5BOpci%C3%B3n%202%5D%0A%20%20%20%20A%20--%3E%20D%5BOpci%C3%B3n%203%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BProbabilidad%20de%20%C3%A9xito%5D%0A%20%20%20%20B%20--%3E%20F%5BRecompensa%20si%20tiene%20%C3%A9xito%5D%0A%20%20%20%20B%20--%3E%20G%5BCosto%20en%20caso%20de%20falla%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BProbabilidad%20de%20%C3%A9xito%5D%0A%20%20%20%20C%20--%3E%20I%5BRecompensa%20si%20tiene%20%C3%A9xito%5D%0A%20%20%20%20C%20--%3E%20J%5BCosto%20en%20caso%20de%20falla%5D%0A%0A%20%20%20%20D%20--%3E%20K%5BProbabilidad%20de%20%C3%A9xito%5D%0A%20%20%20%20D%20--%3E%20L%5BRecompensa%20si%20tiene%20%C3%A9xito%5D%0A%20%20%20%20D%20--%3E%20M%5BCosto%20en%20caso%20de%20falla%5D%0A%0A%20%20%20%20E%20--%3E%20N%5BValor%20esperado%5D%0A%20%20%20%20F%20--%3E%20N%0A%20%20%20%20G%20--%3E%20N%0A%0A%20%20%20%20H%20--%3E%20O%5BValor%20esperado%5D%0A%20%20%20%20I%20--%3E%20O%0A%20%20%20%20J%20--%3E%20O%0A%0A%20%20%20%20K%20--%3E%20P%5BValor%20esperado%5D%0A%20%20%20%20L%20--%3E%20P%0A%20%20%20%20M%20--%3E%20P%0A%0A%20%20%20%20N%20--%3E%20Q%5BElija%20el%20mejor%20veh%C3%ADculo%20el%C3%A9ctrico%5D%0A%20%20%20%20O%20--%3E%20Q%0A%20%20%20%20P%20--%3E%20Q%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20Q%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...u[0]||(u[0]=[l(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=r('<h2 id="el-marco-basico" tabindex="-1">El marco básico <a class="header-anchor" href="#el-marco-basico" aria-label="Permalink to &quot;El marco básico&quot;">​</a></h2><p>Cada lanzamiento tiene tres componentes:</p><table tabindex="0"><thead><tr><th>Componente</th><th>Pregunta</th><th>Ejemplo</th></tr></thead><tbody><tr><td><strong>Probabilidad de éxito</strong></td><td>¿Qué probabilidad hay de que ejecute esto?</td><td>70% de tasa de éxito a esta distancia</td></tr><tr><td><strong>Recompensa si tiene éxito</strong></td><td>¿Qué gano?</td><td>Gana el punto, gana posición</td></tr><tr><td><strong>Costo en caso de fracaso</strong></td><td>¿Qué pierdo?</td><td>Darle un punto fácil al oponente</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">La fórmula</p><p><strong>Valor esperado = (Probabilidad × Recompensa) - ((1 - Probabilidad) × Costo)</strong></p><p>Las buenas decisiones maximizan el valor esperado a lo largo del tiempo.</p></div><h2 id="pensando-en-probabilidades" tabindex="-1">Pensando en probabilidades <a class="header-anchor" href="#pensando-en-probabilidades" aria-label="Permalink to &quot;Pensando en probabilidades&quot;">​</a></h2><p>Al decidir entre las opciones, considere:</p><ul><li>¿Cuál es mi tasa de éxito realista para cada opción?</li><li>¿Qué gano si funciona?</li><li>¿Cuál es el costo si falla?</li><li>¿Cómo afecta la situación del juego a mi elección?</li></ul><p>La mejor opción no siempre es la más agresiva ni la más segura: es la que ofrece el mejor resultado en muchas situaciones similares.</p><h2 id="conozca-sus-numeros" tabindex="-1">Conozca sus números <a class="header-anchor" href="#conozca-sus-numeros" aria-label="Permalink to &quot;Conozca sus números&quot;">​</a></h2><p>Para utilizar el pensamiento probabilístico, necesita conocer sus tasas de éxito reales:</p><table tabindex="0"><thead><tr><th>Tipo de lanzamiento</th><th>Distancia</th><th>Su tasa de éxito</th></tr></thead><tbody><tr><td>Punto (cerrar)</td><td>6-7 meses</td><td>___%</td></tr><tr><td>Punto (medio)</td><td>8-9 meses</td><td>___%</td></tr><tr><td>Punto (largo)</td><td>10 m+</td><td>___%</td></tr><tr><td>Disparar (cerrar)</td><td>6-7 meses</td><td>___%</td></tr><tr><td>Disparar (medio)</td><td>8-9 meses</td><td>___%</td></tr><tr><td>Disparar (largo)</td><td>10 m+</td><td>___%</td></tr></tbody></table>',11)),s(q),u[5]||(u[5]=r('<p>Monitorea esto en la práctica. Sé honesto: la mayoría de los jugadores sobreestiman sus probabilidades de éxito.</p><h2 id="ajuste-a-las-condiciones" tabindex="-1">Ajuste a las condiciones <a class="header-anchor" href="#ajuste-a-las-condiciones" aria-label="Permalink to &quot;Ajuste a las condiciones&quot;">​</a></h2><p>Sus tarifas base cambian en función de:</p><table tabindex="0"><thead><tr><th>Factor</th><th>Efecto en la tasa de éxito</th></tr></thead><tbody><tr><td>Terreno desconocido</td><td>-10 a -20%</td></tr><tr><td>Situación de presión</td><td>-5 a -15%</td></tr><tr><td>Fatiga</td><td>-5 a -10%</td></tr><tr><td>Confianza (alta)</td><td>+5 a +10%</td></tr><tr><td>Éxito reciente</td><td>+5%</td></tr><tr><td>Fallo reciente</td><td>-5 a -10%</td></tr></tbody></table><p>Sea realista acerca de estos ajustes.</p><h2 id="el-principio-de-la-ventaja-de-boule" tabindex="-1">El principio de la ventaja de Boule <a class="header-anchor" href="#el-principio-de-la-ventaja-de-boule" aria-label="Permalink to &quot;El principio de la ventaja de Boule&quot;">​</a></h2><p>Cuando te quedan más bolas que a tu oponente:</p><p><strong>Prioridad 1: Asegurar el punto</strong></p><ul><li>Primero, asegúrate de tener al menos un punto</li><li>No seas codicioso antes de haber asegurado lo básico</li></ul><p><strong>Prioridad 2: Maximizar puntos con riesgo calculado</strong></p><ul><li>Una vez que tengas la posesión, evalúa si puedes sumar más puntos.</li><li>Cada lanzamiento adicional es una decisión de riesgo/recompensa.</li><li>No conviertas una victoria segura de 2 puntos en una derrota por excederte</li></ul><p><strong>Menos bolas restantes:</strong> Debes aprovechar cada lanzamiento. Las jugadas seguras podrían no ser suficientes; considera opciones con mayor recompensa para recuperar la apuesta al final.</p><h2 id="el-principio-quot-une-boule-devant-quot" tabindex="-1">El principio &quot;Une Boule Devant&quot; <a class="header-anchor" href="#el-principio-quot-une-boule-devant-quot" aria-label="Permalink to &quot;El principio &amp;quot;Une Boule Devant&amp;quot;&quot;">​</a></h2><p>Una bola delante del boliche (entre el boliche y el oponente) es extremadamente valiosa:</p><ul><li>Bloquea líneas de señalización directa.</li><li>Obliga a los oponentes a rodearlos o pasarlos por encima.</li><li>Puede desviar las bolas entrantes</li><li>Es una &quot;bola de dinero&quot; que vale la pena proteger.</li></ul><p><strong>Implicación táctica:</strong> A veces, colocar una bola de bloqueo es mejor que intentar acercarse más.</p><h2 id="tolerancia-al-riesgo-segun-el-estado-del-juego" tabindex="-1">Tolerancia al riesgo según el estado del juego <a class="header-anchor" href="#tolerancia-al-riesgo-segun-el-estado-del-juego" aria-label="Permalink to &quot;Tolerancia al riesgo según el estado del juego&quot;">​</a></h2><h3 id="con-limite-de-tiempo" tabindex="-1">Con límite de tiempo <a class="header-anchor" href="#con-limite-de-tiempo" aria-label="Permalink to &quot;Con límite de tiempo&quot;">​</a></h3><p>Al jugar con un límite de tiempo, la diferencia de puntuación importa:</p><table tabindex="0"><thead><tr><th>Situación de puntuación</th><th>Enfoque de riesgo</th></tr></thead><tbody><tr><td>Liderando por 4+</td><td>Muy conservador: proteger el liderazgo y hacer correr el reloj.</td></tr><tr><td>Liderando por 1-3</td><td>Conservador: no regalas puntos</td></tr><tr><td>Atado</td><td>Riesgos equilibrados y calculados</td></tr><tr><td>Por detrás por 1-3</td><td>Agresivo: necesidad de ganar terreno</td></tr><tr><td>Detrás por 4+</td><td>Muy agresivo: hay que arriesgarse, el tiempo se acaba.</td></tr></tbody></table><h3 id="sin-limite-de-tiempo" tabindex="-1">Sin límite de tiempo <a class="header-anchor" href="#sin-limite-de-tiempo" aria-label="Permalink to &quot;Sin límite de tiempo&quot;">​</a></h3><p>Cuando no hay presión de tiempo:</p><ul><li>Mantén tu plan de juego: no cambies la estrategia solo por el marcador.</li><li>La puntuación fluctuará: confíe en su enfoque</li><li>Solo considere cambiar su plan de juego si claramente no está funcionando contra este oponente.</li><li>Los cambios de pánico cuando uno se queda atrás a menudo empeoran las cosas</li></ul><h3 id="ajustes-del-final-del-juego" tabindex="-1">Ajustes del final del juego <a class="header-anchor" href="#ajustes-del-final-del-juego" aria-label="Permalink to &quot;Ajustes del final del juego&quot;">​</a></h3><p><strong>Si al ganar este final se gana el juego:</strong></p><ul><li>Sea más conservador</li><li>No te arriesgues a ceder varios puntos</li><li>Un solo punto podría ser suficiente</li></ul><p><strong>Si pierdes este final pierdes el juego:</strong></p><ul><li>Tomar riesgos mayores</li><li>Necesitas sumar varios puntos</li><li>El juego seguro no te salvará</li></ul><h2 id="errores-comunes-de-probabilidad" tabindex="-1">Errores comunes de probabilidad <a class="header-anchor" href="#errores-comunes-de-probabilidad" aria-label="Permalink to &quot;Errores comunes de probabilidad&quot;">​</a></h2><h3 id="_1-exceso-de-confianza" tabindex="-1">1. Exceso de confianza <a class="header-anchor" href="#_1-exceso-de-confianza" aria-label="Permalink to &quot;1. Exceso de confianza&quot;">​</a></h3><p>&quot;Puedo encestar ese tiro&quot;, pero ¿lo harás 7 de cada 10 veces? Sé honesto.</p><h3 id="_2-ignorar-las-tasas-base" tabindex="-1">2. Ignorar las tasas base <a class="header-anchor" href="#_2-ignorar-las-tasas-base" aria-label="Permalink to &quot;2. Ignorar las tasas base&quot;">​</a></h3><p>Tu porcentaje de tiro no cambia porque el momento sea importante.</p><h3 id="_3-falacia-del-costo-hundido" tabindex="-1">3. Falacia del costo hundido <a class="header-anchor" href="#_3-falacia-del-costo-hundido" aria-label="Permalink to &quot;3. Falacia del costo hundido&quot;">​</a></h3><p>&quot;Ya fallé dos veces, debería seguir disparando&quot; - cada lanzamiento es independiente.</p><h3 id="_4-sesgo-de-resultado" tabindex="-1">4. Sesgo de resultado <a class="header-anchor" href="#_4-sesgo-de-resultado" aria-label="Permalink to &quot;4. Sesgo de resultado&quot;">​</a></h3><p>Un tiro arriesgado que funcionó seguía siendo arriesgado. Una jugada segura que falló seguía siendo correcta.</p><h3 id="_5-ignorar-las-opciones-del-oponente" tabindex="-1">5. Ignorar las opciones del oponente <a class="header-anchor" href="#_5-ignorar-las-opciones-del-oponente" aria-label="Permalink to &quot;5. Ignorar las opciones del oponente&quot;">​</a></h3><p>Piensa en lo que harán después de tu lanzamiento, tenga éxito o no.</p><h2 id="aplicacion-practica" tabindex="-1">Aplicación práctica <a class="header-anchor" href="#aplicacion-practica" aria-label="Permalink to &quot;Aplicación práctica&quot;">​</a></h2><h3 id="antes-de-cada-lanzamiento" tabindex="-1">Antes de cada lanzamiento <a class="header-anchor" href="#antes-de-cada-lanzamiento" aria-label="Permalink to &quot;Antes de cada lanzamiento&quot;">​</a></h3><ol><li><strong>Identificar opciones</strong> (apuntar, disparar, bloquear, etc.)</li><li><strong>Estimar la probabilidad de éxito</strong> para cada uno</li><li><strong>Considere los resultados</strong> (éxito y fracaso)</li><li><strong>Tenga en cuenta el estado del juego</strong> (puntuación, bolas restantes)</li><li><strong>Elija</strong> la opción con el mejor valor esperado</li><li><strong>Comprometerse plenamente</strong> - sin dudas durante la ejecución</li></ol><h3 id="desarrollando-la-intuicion" tabindex="-1">Desarrollando la intuición <a class="header-anchor" href="#desarrollando-la-intuicion" aria-label="Permalink to &quot;Desarrollando la intuición&quot;">​</a></h3><p>Con el tiempo, el pensamiento probabilístico se vuelve intuitivo:</p><ul><li>Realice un seguimiento honesto de sus resultados</li><li>Revisar las decisiones después de los partidos</li><li>Observe patrones en sus tasas de éxito</li><li>Ajusta tu modelo mental</li></ul><h2 id="conclusion-clave" tabindex="-1">Conclusión clave <a class="header-anchor" href="#conclusion-clave" aria-label="Permalink to &quot;Conclusión clave&quot;">​</a></h2><blockquote><p>Las buenas decisiones no siempre conducen a buenos resultados. Pero las buenas decisiones, con el tiempo, conducen a mejores resultados.</p></blockquote><p>Piensa en probabilidades. Conoce tus números. Haz la jugada inteligente, no la optimista.</p>',48)),s(g)])}]]);export{u as __pageData,p as default};
